mapper.select:
SELECT a.`id` AS "id", a.`theme` AS "theme", a.`content_description` AS "contentDescription", a.`safety_education_type` AS "safetyEducationType", a.`start_time` AS "startTime", a.`participants` AS "participants", a.`participants_name` AS "participantsName", a.`safety_status` AS "safetyStatus", a.`participation_type` AS "participationType", a.`attachment_url` AS "attachmentUrl", a.`create_time` AS "createTime", a.`update_time` AS "updateTime", a.`status` AS "status" FROM `swm_safety_education` a
a.`status` = 0
AND a.`theme` LIKE CONCAT('%', #{theme}, '%')
AND a.`safety_education_type` = #{safetyEducationType}
AND a.`participation_type` = #{participationType}
AND a.`safety_status` = #{safetyStatus}
ORDER BY a.update_time DESC
